<script>
function vpnUsersPage(){return{modal:false,importModal:false,historyModal:false,editing:false,form:{},historyClient:{connections:[]},init(){const form=this.$root.querySelector('[x-show="modal"] form');const actions=form?.lastElementChild;if(!form||!actions)return;const section=document.createElement('section');section.className='space-y-3 rounded-xl border border-gray-200 p-4 sm:col-span-2 dark:border-gray-700';section.innerHTML=`<label class="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" name="schedule_enabled" value="1" x-model="form.schedule_enabled" class="rounded border-gray-300"> Batasi akses berdasarkan jadwal</label><div x-show="form.schedule_enabled" x-cloak class="space-y-3"><div><span class="mb-2 block text-xs font-medium">Hari akses</span><div class="flex flex-wrap gap-2">${[['1','Sen'],['2','Sel'],['3','Rab'],['4','Kam'],['5','Jum'],['6','Sab'],['7','Min']].map(([day,label])=>`<label class="inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs"><input type="checkbox" name="schedule_days[]" value="${day}" x-model="form.schedule_days" class="rounded border-gray-300"> ${label}</label>`).join('')}</div></div><div class="grid grid-cols-2 gap-3"><label class="text-sm"><span class="mb-1 block text-xs font-medium">Jam mulai</span><input type="time" name="schedule_start" x-model="form.schedule_start" class="w-full rounded-lg border-gray-300 bg-transparent dark:border-gray-700"></label><label class="text-sm"><span class="mb-1 block text-xs font-medium">Jam selesai</span><input type="time" name="schedule_end" x-model="form.schedule_end" class="w-full rounded-lg border-gray-300 bg-transparent dark:border-gray-700"></label></div><p class="text-xs text-gray-500">Zona waktu Asia/Jakarta. Jadwal dapat melewati tengah malam.</p></div>`;form.insertBefore(section,actions);Alpine.initTree(section)},openCreate(){this.editing=false;this.form={status:'active',vpn_group_id:'',allowed_destinations_text:'',schedule_enabled:false,schedule_days:['1','2','3','4','5'],schedule_start:'08:00',schedule_end:'17:00'};this.modal=true},openEdit(client){const schedule=client.access_schedule||{};this.editing=true;this.form={...client,vpn_group_id:client.vpn_group_id||'',allowed_destinations_text:(client.allowed_destinations||[]).join('\n'),schedule_enabled:!!client.access_schedule,schedule_days:(schedule.days||[]).map(String),schedule_start:schedule.start||'08:00',schedule_end:schedule.end||'17:00'};this.modal=true},openHistory(client){this.historyClient=client;this.historyModal=true},formatDate(value){return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))},formatBytes(value){if(value<1024)return value+' B';if(value<1048576)return(value/1024).toFixed(1)+' KB';if(value<1073741824)return(value/1048576).toFixed(1)+' MB';return(value/1073741824).toFixed(1)+' GB'}}}
</script>
<script>
document.addEventListener('change', function (event) {
    if (event.target.matches('input[name="schedule_days[]"]')) {
        event.stopImmediatePropagation();
    }
}, true);
document.addEventListener('submit', function (event) {
    const form = event.target;
    const enabled = form.querySelector('input[name="schedule_enabled"]');
    if (!enabled) return;
    enabled.value = '1';
    form.querySelectorAll('input[name="schedule_days[]"]').forEach(function (input, index) {
        input.value = String(index + 1);
    });
}, true);
</script>
